'use strict';

/**
* Evaluate the Gaussian Error Linear Unit (GELU) activation function.
*
* @module @stdlib/math/base/special/gelu
*
* @example
* var gelu = require( '@stdlib/math/base/special/gelu' );
*
* var y = gelu( 0.0 );
* // returns 0.0
*
* y = gelu( 1.0 );
* // returns ~0.8413
*
* y = gelu( -Infinity );
* // returns -0.0
*
* y = gelu( NaN );
* // returns NaN
*
* @example
* var gelu = require( '@stdlib/math/base/special/gelu' );
*
* var y = gelu.tanh( 0.0 );
* // returns 0.0
*
* y = gelu.tanh( 1.0 );
* // returns ~0.8412
*
* @example
* var gelu = require( '@stdlib/math/base/special/gelu' );
*
* var y = gelu.quick( 0.0 );
* // returns 0.0
*
* y = gelu.quick( 1.0 );
* // returns ~0.8458
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var quick = require( './quick.js' );
var tanh = require( './tanh.js' );
var main = require( './main.js' );


// MAIN //

setReadOnly( main, 'tanh', tanh );
setReadOnly( main, 'quick', quick );


// EXPORTS //

module.exports = main;
